package turbo.gauntlet;
import java.util.*;
import net.runelite.api.coords.WorldPoint;
public final class GauntletStateTests {
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 private static GauntletState.Snapshot snap(int tick,boolean instance,boolean start,boolean boss,boolean reward,boolean hazard){return new GauntletState.Snapshot(tick,90,80,12,2,3,3,100,true,instance,false,start,true,boss,reward,boss,reward,reward,reward,hazard,false);}
 public static void main(String[] args){
  GauntletState state=new GauntletState();state.reset(GauntletState.Mode.AUTO_DETECT);check(state.step(snap(1,false,false,false,false,false),false).kind==GauntletState.ActionKind.OBSERVE,"unknown instance gates input");state.step(snap(2,true,true,false,false,false),false);state.step(snap(3,true,true,false,false,false),false);for(int i=4;i<20&&state.phase()!=GauntletState.Phase.ENTER_HUNLLEF;i++)state.step(snap(i,true,true,false,false,false),false);check(state.mode()==GauntletState.Mode.REGULAR,"auto detect regular");GauntletState.Decision hazard=state.step(snap(30,true,true,true,false,true),true);check(hazard.kind==GauntletState.ActionKind.MOVE&&hazard.priority==1000,"hazard preempts all");
  GauntletSignals signals=new GauntletSignals();check(!signals.controlReady()&&!signals.missing().isEmpty(),"unverified IDs never arm control");
  GauntletPlanner graph=new GauntletPlanner();graph.connect("A","B");graph.connect("B","C");check(graph.path("A","C").size()==3,"dynamic room graph path");
  testActionContract();testResources();testHunllef();testTimedPath(graph);
  System.out.println("Gauntlet checks passed: safe gate, acknowledged actions, resources, Hunllef cycles, hazard priority and time-expanded paths.");
 }
 private static void testActionContract(){GauntletActionContract c=new GauntletActionContract();GauntletActionContract.Request r=c.submit(GauntletActionContract.Type.EQUIP,"bow","weapon=bow",10,2,1);check(c.observe(r,10,s->false)==GauntletActionContract.Status.PENDING,"submission cannot confirm itself");check(c.observe(r,12,s->false)==GauntletActionContract.Status.RETRY,"timeout requests bounded retry");c.markResubmitted(r);check(c.observe(r,13,s->s.equals("weapon=bow"))==GauntletActionContract.Status.CONFIRMED,"postcondition confirms action");GauntletActionContract.Request stale=c.submit(GauntletActionContract.Type.MOVE,"tile","at=tile",20,2,0);c.reset();check(c.observe(stale,21,s->true)==GauntletActionContract.Status.CANCELLED,"old generation is cancelled");}
 private static void testResources(){GauntletResourceLedger l=new GauntletResourceLedger();l.require("ore",3);l.observe("ore",3,"inventory",1);check(l.reserve("ore",2)&&!l.reserve("ore",2),"reservations prevent double spend");check(l.spendReserved("ore",2)&&l.get("ore").available()==1,"reserved spend is accounted");check(l.get("ore").shortage()==2,"spent material remains required for plan completion");}
 private static void testHunllef(){HunllefTracker t=new HunllefTracker();for(int i=1;i<=4;i++)t.observeBossAttack(i,HunllefTracker.EventKind.PROJECTILE_ATTACK,HunllefTracker.Style.MAGIC);t.observeBossAttack(4,HunllefTracker.EventKind.PROJECTILE_ATTACK,HunllefTracker.Style.MAGIC);t.observeBossAttack(5,HunllefTracker.EventKind.STOMP,HunllefTracker.Style.RANGED);check(t.attacksInStyle()==4&&t.expectedNext()==HunllefTracker.Style.RANGED,"duplicate and stomp do not corrupt four-attack cycle");for(int i=0;i<6;i++)t.observePlayerAttack(false,"PROTECT_MAGIC");check(t.overheadSwitchExpected(),"six off-prayer hits predict overhead switch");}
 private static void testTimedPath(GauntletPlanner p){WorldPoint a=new WorldPoint(0,0,0),b=new WorldPoint(2,0,0);GauntletPlanner.TimedHazards h=new GauntletPlanner.TimedHazards();h.startTick=100;h.horizon=5;h.activatesAt.put(new WorldPoint(1,0,0),101);List<GauntletPlanner.TimedStep> route=p.safePath(a,b,h);check(!route.isEmpty(),"planner finds route around future active tile");for(GauntletPlanner.TimedStep s:route)check(!(s.tile.equals(new WorldPoint(1,0,0))&&s.tick>=101),"entire path, not endpoint, is hazard safe");GauntletPlanner.TimedHazards sealed=new GauntletPlanner.TimedHazards();sealed.startTick=1;sealed.horizon=2;sealed.blocked.add(new WorldPoint(1,0,0));sealed.blocked.add(new WorldPoint(0,1,0));sealed.blocked.add(new WorldPoint(0,-1,0));sealed.blocked.add(new WorldPoint(-1,0,0));check(p.safePath(a,b,sealed).isEmpty(),"no safe path returns empty rather than guessing");}
}
